import{_ as t,o as s,c as a,a4 as i}from"./chunks/framework.kn7HWrZO.js";const u=JSON.parse('{"title":"Development guide","description":"","frontmatter":{"editSource":"docs/development.md","rawMarkdownPath":"en/reference/development.md"},"headers":[],"relativePath":"en/reference/development.md","filePath":"en/reference/development.md"}'),o={name:"en/reference/development.md"};function n(r,e,d,c,l,p){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="development-guide" tabindex="-1">Development guide <a class="header-anchor" href="#development-guide" aria-label="Permalink to &quot;Development guide&quot;">​</a></h1><p>The setup tutorial takes a new contributor from prerequisites to a checked checkout. The contributor reference that follows covers repository layout, daily workflow, and CI organization. Design rationale and implementation details belong to the linked Agent Notes and scripts.</p><h2 id="setup-tutorial" tabindex="-1">Setup tutorial <a class="header-anchor" href="#setup-tutorial" aria-label="Permalink to &quot;Setup tutorial&quot;">​</a></h2><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>Node.js 24.9 or newer. CI covers 24.9, the latest 24, and 26; see the <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.agents/notes/implemented/process/2026-10-15-node-24-runtime-floor.md" target="_blank" rel="noreferrer">Node engine floor Agent Note</a>.</li><li>Node.js TypeScript type stripping enabled. The repository build scripts load <code>tsdown.config.ts</code> with tsdown&#39;s native config loader, so they fail when <code>--no-experimental-strip-types</code> is in <code>NODE_OPTIONS</code> or the Node.js build lacks TypeScript support; <code>pnpm run build</code> checks this first and names the cause.</li><li>Corepack-enabled pnpm. The repo pins <code>pnpm@11.28.5</code> in <code>package.json</code>; run <code>corepack enable</code> if <code>pnpm --version</code> does not resolve through Corepack.</li><li>Git 2.26 or newer; hook setup enables Git&#39;s worktree-specific configuration extension.</li><li>Optional: a DeepSeek API key for the Web, headless, and ACP automation demos and real-API e2e tests.</li></ul><h3 id="windows-and-wsl-2" tabindex="-1">Windows and WSL 2 <a class="header-anchor" href="#windows-and-wsl-2" aria-label="Permalink to &quot;Windows and WSL 2&quot;">​</a></h3><p>On Windows, you can develop with native tools or use WSL 2 for a Linux environment. WSL 2 is useful for verifying Linux behavior and for using Linux toolchains when native dependency compilation or filesystem permissions obstruct Windows development. Each environment needs its own runtime, build tools, and permissions; WSL is optional.</p><p>Keep the checkout, installed dependencies, and toolchain in the same operating system environment. For WSL 2, store the checkout in the Linux filesystem; for native Windows tools, use the Windows filesystem. Accessing files across the two filesystems adds overhead to I/O-intensive operations such as Git, dependency installation, and builds. See Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/windows/wsl/filesystems#file-storage-and-performance-across-file-systems" target="_blank" rel="noreferrer">file storage and performance guidance</a>.</p><p>Install dependencies separately in each environment because native binaries and links can differ between operating systems. Test results apply to the environment where the tests ran; Windows-specific behavior still needs native Windows validation.</p><h3 id="first-time-setup" tabindex="-1">First-time setup <a class="header-anchor" href="#first-time-setup" aria-label="Permalink to &quot;First-time setup&quot;">​</a></h3><p>pnpm uses its strict symlinked linker so undeclared dependencies fail instead of relying on hoisting. Keep dependency build scripts explicitly allowlisted in <code>pnpm-workspace.yaml</code>.</p><p>Install dependencies from the repo root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>The install also configures worktree-local Lefthook hooks through <code>scripts/install-lefthook.mjs</code>. The <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.agents/notes/implemented/process/2026-07-27-worktree-local-lefthook.md" target="_blank" rel="noreferrer">worktree-local hooks Agent Note</a> owns the hook-path safety contract.</p><p>The <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/experimental/inspector/README.md#use-this-package" target="_blank" rel="noreferrer">DevTools frontend</a> is compiled locally from a pinned npm source package and Vite. After dependencies are installed, its build needs no network access or browser installation. Workspace and published-package installation run no DevTools resource-download hook; published Inspector packages contain the built frontend.</p><p>If the hooks are missing because dependencies were restored from cache or <code>postinstall</code> was skipped, install them manually:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/install-lefthook.mjs</span></span></code></pre></div><p>If the wrapper rejects existing Git configuration or reports a stale lock, follow its diagnostic and the linked Agent Note rather than editing worktree metadata speculatively. After moving a checkout, rerun the wrapper to regenerate the owned path.</p><p>Run typecheck once after a fresh clone:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p>Setup is complete when <code>pnpm run typecheck</code> exits successfully.</p><h2 id="contributor-reference" tabindex="-1">Contributor reference <a class="header-anchor" href="#contributor-reference" aria-label="Permalink to &quot;Contributor reference&quot;">​</a></h2><h3 id="typescript-project-layout" tabindex="-1">TypeScript project layout <a class="header-anchor" href="#typescript-project-layout" aria-label="Permalink to &quot;TypeScript project layout&quot;">​</a></h3><p>The repository uses isolated Host and Client aggregates. An ordinary package is registered in exactly one aggregate: Host packages in <code>tsconfig.host.json</code> and Client packages in <code>tsconfig.client.json</code>; three packages (<code>host/webserver</code>, <code>compaction/compaction</code>, <code>typert/registry</code>) are referenced by both aggregates as shared leaves so each side type-checks the same source.</p><table tabindex="0"><thead><tr><th>File</th><th>Role</th><th>Forms a program?</th></tr></thead><tbody><tr><td><code>tsconfig.json</code></td><td>Solution root: <code>extends</code> base, <code>files: []</code>, and references to the two aggregates. It is the tsserver discovery entry and the entry for explicitly running the complete Project Reference graph; through the inherited <code>paths</code>, it is also the resolution config for tsx running <code>scripts/</code>.</td><td>No</td></tr><tr><td><code>tsconfig.host.json</code></td><td>Host aggregate: Host packages, examples, tests, scripts, website, and the exceptional Host project of <code>api/remotes</code>.</td><td>Yes</td></tr><tr><td><code>tsconfig.client.json</code></td><td>Client aggregate: <code>packages/client/*</code> packages and their tests, <code>apps/web</code>, and the exceptional Client project of <code>api/remotes</code>.</td><td>Yes</td></tr><tr><td><code>tsconfig.base.json</code></td><td>Shared compilerOptions and the source <code>paths</code> map. Also the resolution facade the vitest configs point vite-tsconfig-paths at: it has no <code>include</code>, so its <code>paths</code> apply to every importer.</td><td>No</td></tr><tr><td><code>tsconfig.base.client.json</code></td><td>Browser compiler settings (<code>jsx</code>, DOM libs, <code>types: []</code>) extended by the Client aggregate and every <code>packages/client/*</code> package.</td><td>No</td></tr></tbody></table><p>Host and Client aggregate type checks run with an 8 GiB Node old-space limit. This is a per-compiler limit; concurrent build steps need additional memory. <code>pnpm run build:official --serial</code> prevents build steps from overlapping, even with <code>DSH_GATE_CONCURRENCY</code> set; the DSH publication workflow uses this option.</p><p>Host and Client stay two aggregate programs because both sides declaration-merge the cordis <code>Context</code> interface under the same keys with different services; one program seeing both merges reports a collision. The collision exists only inside a <code>ts.Program</code> — module resolution never triggers it — which is why the solution may reference both aggregates and one paths facade may span both sides. Three disciplines follow:</p><ul><li><code>tsconfig.base.json</code> never gains <code>include</code> or <code>files</code>: they would leak into every extending package project and narrow the facade&#39;s match-all scope.</li><li>A script that builds a repo-wide <code>ts.Program</code> seeds <code>tsconfig.host.json</code> or <code>tsconfig.client.json</code> explicitly — never the root solution, because flattening both aggregates into one program collides the <code>Context</code> merges.</li><li>A new package is registered in exactly one aggregate; only the split packages above carry both leaf configs, and the shared leaves are registered in both aggregates because each side must type-check the same source. Having both a Node loader entry and a browser entry is not a reason to split a package; an ordinary Client plugin produces both runtime artifacts during the Client build phase.</li></ul><p>Seven packages split Host and Client tsconfigs: <code>api/remotes</code>, <code>api/gateway</code>, <code>api/session-controller</code>, <code>api/workspace-controller</code>, <code>client/connection</code>, <code>session-query/session-log-export</code>, and <code>experimental/liveshare-protocol</code>. <code>api/remotes</code>&#39; Host entry participates in the Host Typert graph while its Client entry imports generated <code>/remote</code> declarations; <code>session-log-export</code> keeps Node archive production out of its browser controller; <code>liveshare-protocol</code> keeps the Node wire codecs on its Host leaf and the browser viewer carrier on its Client leaf. Each split package-root <code>tsconfig.json</code> is therefore only a solution, and the two aggregates and direct consumers reference <code>tsconfig.host.json</code> or <code>tsconfig.client.json</code> respectively. The workspace <code>constraints</code> gate walks the reachable Project Reference graph and checks each referencing project&#39;s own compiler face: a single-config target remains valid from either face, while a split target must name the matching leaf rather than its solution root or opposite leaf; it discovers split packages from the presence of both leaf configs, so a new split joins the gate automatically. The <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/api/remotes/README.md" target="_blank" rel="noreferrer"><code>api-remotes</code> README</a> and <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/session-query/session-log-export/README.md" target="_blank" rel="noreferrer"><code>session-log-export</code> README</a> explain their splits.</p><p><code>pnpm run build:artifacts</code> emits every artifact, checking and compiling only the package references of each compiler face. Client compilation waits for Host and Desktop bundling to finish: split compiler faces rewrite shared <code>lib/types</code> files read by those bundles. Client bundling follows Client compilation. The artifact order is:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:native-system</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/generate-typert.ts</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tsconfig.host.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reference</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsdown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env.DSH_BUILD_FACE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> host</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @deepseek-ai/dsh-desktop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bundle</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">tsconfig.client.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reference</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tsdown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env.DSH_BUILD_FACE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:web</span></span></code></pre></div><p><code>pnpm run build:check</code> runs only <code>tsc -p tsconfig.host.json</code> and <code>tsc -p tsconfig.client.json</code> concurrently. Project mode checks each aggregate&#39;s repository-wide test and script program against the package declarations already on disk and never compiles a reference, so <code>build:check</code> neither detects nor rebuilds missing or stale <code>build:artifacts</code> output; missing output surfaces as compiler errors. <code>pnpm run build</code> runs both step sets as one <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/scripts/run-gates.ts" target="_blank" rel="noreferrer">scheduled</a> dependency graph: each aggregate check starts once its own face&#39;s package compilation finishes and overlaps the remaining artifact steps. In all three commands <code>DSH_GATE_CONCURRENCY</code> bounds concurrent steps (<code>1</code> runs them in dependency order) and <code>DSH_GATE_FAIL_FAST=1</code> stops the remaining steps at the first failure; otherwise a failure skips only its dependents, so independent errors are all reported. A failed step prints its own output, and any failure exits non-zero without writing the client build record. Host TypeScript compiler processes receive an 8 GiB V8 old-space limit for the package graph and cold aggregate checks.</p><p>Choose the command by what the change needs:</p><table tabindex="0"><thead><tr><th>Situation</th><th>Command</th></tr></thead><tbody><tr><td>Iterating on package sources and needing runnable artifacts</td><td><code>pnpm run build:artifacts</code>; <code>dev:web</code> and <code>dev:desktop</code> run it before launching</td></tr><tr><td>Type-checking tests, scripts, benchmarks, or website code</td><td><code>pnpm run build:check</code> after the latest <code>build:artifacts</code>; rerun <code>build:artifacts</code> first when package sources changed</td></tr><tr><td>Before declaring TypeScript work complete</td><td><code>pnpm run build:check</code> after the latest <code>build:artifacts</code>, or <code>pnpm run build</code></td></tr><tr><td>Complete verification, as the required CI build lanes run it</td><td><code>pnpm run build</code></td></tr><tr><td>Type checks without the Web and Desktop artifacts</td><td><code>pnpm run typecheck</code></td></tr><tr><td>Lint or documentation code-block checks</td><td><code>pnpm run lint</code> or <code>pnpm run doc-typecheck</code>; each prepares <code>host-contracts</code> itself</td></tr></tbody></table><p>PR artifact builders run <code>build:artifacts</code>; required Linux and Windows normal builds and public <code>typecheck</code> also check the repository-wide test and script programs. CI benchmark preparation additionally uses <code>--noCheck</code> for its disposable library outputs, relying on those required builds for diagnostics; other artifact builders keep package checking (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.agents/notes/implemented/process/2026-10-05-pr-artifact-typechecks.md" target="_blank" rel="noreferrer">rationale</a>).</p><p>Both tsdown passes match <code>vendor/*</code>, <code>packages/*/*</code>, and <code>apps/cli</code>; the Host pass also matches <code>apps/desktop-host</code>. They neither scan build artifacts to discover Client packages nor maintain a Host/Client package filter list. Package-local tsdown configs select entries for the current phase through <code>DSH_BUILD_FACE</code>: an ordinary Client plugin produces both its Node loader and browser bundle during the Client phase; <code>api-remotes</code> uses <code>hostPhase: true</code> to produce its Host entry early and only its browser bundle during the Client phase. Tsdown consumes only the JavaScript emitted to <code>lib/types</code> by the preceding tsc phase. Tsdown builds the matched workspace members concurrently, so <code>apps/desktop</code>, whose main bundle inlines workspace devDependencies from their <code>lib/</code> output, bundles in its own step after the Host pass (<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/apps/desktop/README.md#bundled-workspace-dependencies" target="_blank" rel="noreferrer">Desktop README</a>).</p><p>Typert analyzes Host types through <code>tsconfig.host.json</code> and generates Host reflection and Host-for-Client Remote declarations before package compilation. The source-only <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/scripts/generate-typert.ts" target="_blank" rel="noreferrer"><code>generate-typert.ts</code></a> pass rejects workspace imports that require built output, including metadata dependencies that return to generated declarations. Host tsdown lowers source decorators without generating metadata again; Client tsdown also consumes the existing metadata. <code>pnpm run typecheck</code> generates metadata, compiles Host and Client packages in reference order, and checks each aggregate with <code>tsc -b</code> after its package compilation. It skips the native addon, bundles, Web, and the client build record. <code>lint</code>, <code>lint:fix</code>, and <code>doc-typecheck</code> prepare metadata and Host package declarations through <code>compile-referenced-projects.ts host-contracts</code>; generation failure stops dependent compilation. These declaration-only commands do not update runtime bundles: run <code>build:artifacts</code> before launching or testing built output.</p><p><code>pnpm run build</code> and <code>build:artifacts</code> embed the root package version, the seven-character source commit, and a dirty marker when Git reports local changes; they also inherit other caller-supplied <code>DSH_CLIENT_*</code> values. <code>pnpm run build:official</code> is the cross-platform local equivalent of the CI and release artifact build and omits the local dirty marker. Each successful <code>build</code> or <code>build:artifacts</code> writes a gitignored record that binds the exact public values to the Vite output and dynamic client bundles; release packing and built Web tests reject a missing record or artifacts changed by a later partial build. <code>pnpm run dev:web</code> runs <code>build:artifacts</code> first (<code>--skip-build</code> reuses an existing artifact tree instead), then samples the current version and Git state once and shares that environment across every watcher stage for the session; it does not validate the complete-build record because the watcher stages rewrite its recorded artifacts.</p><p><code>pnpm run build --profile local</code> explicitly selects local client branding, preserves repository version, commit and dirty metadata, and discards inherited client title and other public overrides. <code>build:official</code> retains its exact official values. <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/apps/desktop/packaging/README.md#configuration-and-local-builds" target="_blank" rel="noreferrer">Desktop packaging</a> selects the profile for each signing mode.</p><p>Static analysis and tests resolve workspace imports through the base <code>paths</code> map to <code>src</code> and must pass on a clean tree; gates that consume built <code>lib/</code> output declare that dependency explicitly. Generated Host-for-Client Remote declarations are the deliberate exception: the public <code>typecheck</code>, <code>lint</code>, and <code>doc-typecheck</code> commands generate them first, while internal <code>*:contracts-ready</code> scripts assume that an invoking public command or scheduler gate already depends on the Typert contract-generation pass or the complete build. See the <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.agents/notes/implemented/architecture/2026-08-02-typert-remote-method-calls.md" target="_blank" rel="noreferrer">Typert Remote note</a> for the gate-preparation contract.</p><p>Business services declare callable methods on the Host with <code>@Remote</code> or <code>@RemoteScope</code>; the Host build generates Host-for-Client types and runtime contributions, and the Client&#39;s <code>api-remotes</code> composition loads those contributions under <code>ctx.remote</code> and scoped <code>agentCtx.remote</code> namespaces. See <a href="./api-gateway.html">API Gateway</a> for the generated artifacts on both sides, their assembly relationships, the SRC development fallback, and the Web build order.</p><p>If a relevant local check consumes built package output, build once first:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p><code>pnpm run hygiene</code> includes <code>publint</code>, which validates package entrypoints against the built <code>lib/*.js</code> files, and <code>verify-node-next-types</code>, which validates built declarations against a temporary NodeNext consumer. A fresh worktree has no bundled JS or declarations until <code>pnpm run build</code> runs; ordinary commits and pushes do not require that build unless their selected checks consume it.</p><h3 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h3><p>The real DeepSeek adapter and key-backed agent demos read credentials from the environment or from a gitignored <code>.env</code> at the repo root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEEPSEEK_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-...</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEEPSEEK_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://...</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # optional</span></span></code></pre></div><p><code>DEEPSEEK_BASE_URL</code> is optional and defaults to the public API. Never commit real credentials. The real-API e2e suites self-skip when <code>DEEPSEEK_API_KEY</code> is not set.</p><h3 id="git-integrations" tabindex="-1">Git integrations <a class="header-anchor" href="#git-integrations" aria-label="Permalink to &quot;Git integrations&quot;">​</a></h3><p><code>.i18n.yaml</code> records use Git&#39;s default text merge. A record conflicts only when both branches changed language-specific content in the same heading section; resolve the Markdown, then rerun <code>pnpm run verify-translation-pairing --write &lt;pair&gt;</code>. If <code>pre-merge-commit</code> rejects an otherwise clean merge, Git leaves the complete result staged without a commit; repair the failure and run <code>git commit</code>, or run <code>git merge --abort</code>.</p><p>lefthook is configured in <code>lefthook.yml</code> as a fast local checkpoint:</p><ul><li><code>pre-commit</code> verifies staged pairing records against the staged owner blobs, validates staged files with the project-free <code>.oxlintrc.staged.json</code> profile and applies Oxlint fixes with one bounded retry, checks the staged diff for whitespace errors, checks pi-ai provider metadata when its inputs or generated file are staged, and runs the vendor manifest guard.</li><li><code>pre-merge-commit</code> performs the same index-backed pairing check before Git creates an automatic merge commit.</li><li><code>pre-push</code> runs <code>pnpm run typecheck</code>, which generates Typert contracts without bundling before the Client TypeScript check and checks both aggregates.</li></ul><p>The vendor manifest guard checks that changes under <code>vendor/*/src</code> are staged with the matching <code>vendor/README.md</code> manifest update. See <code>vendor/README.md</code> before editing vendored code.</p><p>The pi-ai check regenerates expected metadata in memory. It rejects stale data without rewriting or staging files. After a pi-ai dependency or generator change, follow the package&#39;s <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/llm/llm-pi-ai/README.md#generated-provider-metadata" target="_blank" rel="noreferrer">provider metadata update steps</a>.</p><p>Apart from the scoped pairing and provider metadata checks, the hooks intentionally do not run tests, snapshots, documentation checks, builds, or hygiene. Contributors run the <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/AGENTS.md#run-relevant-checks-locally" target="_blank" rel="noreferrer">checks relevant to the changed behavior</a> once; CI owns exhaustive coverage, built-artifact smokes, and the Node 24.9, latest 24, and 26 compatibility matrix.</p><p>Contributors can opt into the comprehensive local gate set with <code>pnpm run check:all</code>. The command is independent of the Git hooks and is not an agent instruction.</p><p>Outside CI (<code>CI</code> other than <code>true</code>), default worker counts follow the <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/scripts/parallelism.ts" target="_blank" rel="noreferrer">local worker budget</a>: 12 for gate schedulers, <code>build</code>, <code>typecheck</code>, Oxlint, and publint, and 48 for Vitest forks and local coverage. <code>doc-sync</code>, <code>test:docs</code>, <code>hygiene</code>, and <code>check:all</code> run at most 8 gates at once, in CI as well. <code>os.availableParallelism()</code> reports host CPUs rather than a container&#39;s CPU quota, so uncapped defaults oversubscribe shared hosts. CI keeps the runner&#39;s CPU count. <code>DSH_GATE_CONCURRENCY</code>, <code>DSH_OXLINT_THREADS</code>, <code>DSH_COVERAGE_MAX_WORKERS</code>, and Vitest <code>--maxWorkers</code> override the defaults.</p><p><code>run-gates</code> gives the CLI help generator one child at a time; direct <code>pnpm run verify-cli-help</code> uses the standalone worker budget. <code>DSH_CLI_HELP_CONCURRENCY</code> overrides that child limit with a positive integer validated before startup. Each invocation retains its private <code>DSH_HOME</code> and <code>DSH_AGENTS_HOME</code> and 30-second deadline.</p><h3 id="ci-gates" tabindex="-1">CI gates <a class="header-anchor" href="#ci-gates" aria-label="Permalink to &quot;CI gates&quot;">​</a></h3><p>The keyless <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.github/workflows/ci.yml" target="_blank" rel="noreferrer">CI workflow</a> groups independent gates into broad lanes and runs a smaller compatibility signal across supported Node versions. Artifact consumers wait for one build within their lane. Coverage partitions reuse file timings scoped to their platform and runner pool to balance work within the configured worker limit. Native Windows lanes run in the separate <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.github/workflows/ci-windows.yml" target="_blank" rel="noreferrer">CI Windows workflow</a> and Python checks in the separate <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.github/workflows/ci-python.yml" target="_blank" rel="noreferrer">CI Python workflow</a>, each of which can be re-run independently. Required benchmarks run separately on standard GitHub-hosted Linux; the <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/benchmarks/AGENTS.md" target="_blank" rel="noreferrer">benchmark runner reference</a> owns routing and the job timeout. The separate real-API workflow runs <code>pnpm run test:e2e</code> with its configured worker bound. See <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/scripts/run-gates.ts" target="_blank" rel="noreferrer">scripts/run-gates.ts</a> and the workflow files for the current gate and job inventory.</p><p>The credential-free dsh dependency-layout and dsh/vendor pack rehearsals use the existing Linux self-hosted pool only when <code>DSH_CI_FAILOVER_LINUX=selfhosted</code> and the event is a trusted master push or same-repository, non-fork, non-Dependabot pull request. All other cases, including manual dispatch, use <code>ubuntu-24.94</code>; manual publication stays hosted. See the <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.agents/notes/implemented/process/2026-07-26-ci-failover-runbook.md" target="_blank" rel="noreferrer">release rehearsal runner reference</a> for persistent-store isolation and fallback limits.</p><h3 id="daily-commands" tabindex="-1">Daily commands <a class="header-anchor" href="#daily-commands" aria-label="Permalink to &quot;Daily commands&quot;">​</a></h3><p>The root <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/AGENTS.md#commands" target="_blank" rel="noreferrer">contributor instructions</a> summarize common commands, while <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/package.json" target="_blank" rel="noreferrer"><code>package.json</code></a> and <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/scripts/run-gates.ts" target="_blank" rel="noreferrer">scripts/run-gates.ts</a> own the current script and gate inventories. Select the smallest checks that cover the changed surface. Documentation changes use <code>pnpm run doc-sync</code>; package-public behavior changes also update the owning README or JSDoc, and built-artifact checks require <code>pnpm run build</code> first.</p><h3 id="profile-runs" tabindex="-1">Profile runs <a class="header-anchor" href="#profile-runs" aria-label="Permalink to &quot;Profile runs&quot;">​</a></h3><p>Run the repository build separately before using these source-checkout demos:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>The one-shot Headless coding agent needs <code>DEEPSEEK_API_KEY</code> in the environment or repo-root <code>.env</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> headless</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;summarize this workspace&quot;</span></span></code></pre></div><p>The PTC mode demo runs the same headless profile with code presentation enabled:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo:ptc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;summarize this workspace&quot;</span></span></code></pre></div><h3 id="application-commands" tabindex="-1">Application commands <a class="header-anchor" href="#application-commands" aria-label="Permalink to &quot;Application commands&quot;">​</a></h3><p>Web and Desktop share one command pair. <code>start:*</code> launches the artifacts of a prior <code>pnpm run build</code> or <code>build:artifacts</code>; <code>dev:*</code> runs <code>build:artifacts</code> first and then launches. Web additionally keeps client bundles rebuilt on source edits, because its Host runs from source while the browser loads built bundles:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:web</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # serve built Web artifacts through the source launcher (the same launch as pnpm dsh web)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:web</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # build, serve, and rebuild Web client bundles on source edits</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:desktop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # launch built Desktop artifacts</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:desktop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # build, then launch Desktop</span></span></code></pre></div><p>Arguments after a Web command reach <code>dsh web</code>, for example <code>pnpm run dev:web --no-open --port 3081</code>; <code>dev:web</code> also accepts <code>--skip-build</code> to reuse the existing artifact tree and <code>--no-serve</code> to run only the rebuild watchers beside a server started elsewhere. Both Web commands use the normal Harness home, while the Desktop commands use the isolated development home described in the <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/apps/desktop/README.md" target="_blank" rel="noreferrer">Desktop README</a>. The root <code>Makefile</code> names the same commands as <code>make web</code>, <code>make dev-web</code>, <code>make desktop</code>, <code>make dev-desktop</code>, and <code>make build</code>; <code>ARGS=&#39;--no-open&#39;</code> forwards options.</p><h3 id="todo-markers" tabindex="-1">TODO markers <a class="header-anchor" href="#todo-markers" aria-label="Permalink to &quot;TODO markers&quot;">​</a></h3><p>Use one of three comment tags to flag known issues in the code, ordered by urgency:</p><ul><li><code>FIXME</code> — an issue that should block a new release. A release should not ship with an open <code>FIXME</code> unless reviewers explicitly agree the change can be merged anyway.</li><li><code>TODO</code> — an issue that should be fixed soon, once we have the resources.</li><li><code>XXX</code> — an issue that we may fix someday; lowest priority, no commitment.</li></ul><p>Pick the tag that matches the urgency so anyone scanning the code can tell a release blocker from a someday-maybe.</p><h3 id="documenting-types-verbatim-ts-type-equiv" tabindex="-1">Documenting types verbatim (<code>ts type-equiv</code>) <a class="header-anchor" href="#documenting-types-verbatim-ts-type-equiv" aria-label="Permalink to &quot;Documenting types verbatim (`ts type-equiv`)&quot;">​</a></h3><p>The <a href="./subsystems/">subsystems</a> pages paste source-equivalent declarations together with their original JSDoc so a reader sees the exact type definition and source contract. To keep a paste from drifting when source changes, fence it as <code>```ts type-equiv</code> (instead of <code>```ts</code>) and register it in <code>scripts/type-equiv.manifest.json</code> with the source file and symbol it mirrors:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;doc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;docs/subsystems/session.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;symbol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SessionEvent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;packages/core/session/src/types.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><code>pnpm run verify-type-equiv</code> (part of <code>doc-sync</code>) then extracts that symbol&#39;s declaration and attached JSDoc from source via the TypeScript parser and asserts the block matches both. For a class whose implementation bodies do not belong in the catalog, use <code>```ts public-api</code> and set <code>&quot;projection&quot;: &quot;public-api&quot;</code>; the checked projection retains the public fields, constructor, accessors, methods, and original class/member JSDoc while omitting bodies and private or protected members. Comparison ignores whitespace and non-JSDoc comments but requires every original JSDoc comment, including member documentation, so readers see the source contract beside the exact type definition. The gate enforces a 1:1 correspondence by document, symbol, and projection between primary blocks and manifest entries; a paired <code>.zh.md</code> block reuses its unsuffixed sibling&#39;s entry only when the whole tracked fence sequence is byte-identical and ordered identically. <code>doc-typecheck</code> applies the same derivative rule to compilable fences, while skipping both source-equivalence fence kinds from compilation and its opt-out ratio. Upgrade guides in version directories older than the root package version are frozen; their examples are excluded from current-API compilation. When you change a documented declaration or its JSDoc, the gate fails until you update the paste; when you add or remove a primary block, update the manifest in the same change.</p>',82)])])}const k=t(o,[["render",n]]);export{u as __pageData,k as default};
